"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6021],{7519(e){e.exports=JSON.parse('{"title":"\ub9ac\uc561\ud2b8\ub9cc \ud558\uba74 \uc7ac\ubbf8\uc5c6\uc9c0 \uc54a\uc73c\uc138\uc694?","date":"2023-09-20","coverUrl":null,"html":"<h2 data-notion-block-id=\\"9400e11a-7604-4e16-83e9-bad55af543c8\\" id=\\"9400e11a-7604-4e16-83e9-bad55af543c8\\">Goodbye, UseEffect</h2><a href=\\"https://www.youtube.com/watch?v=bGzanfKVFeU\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=bGzanfKVFeU</a><p data-notion-block-id=\\"4c6f9cfb-068c-4ab1-973e-5110b35b4a6f\\"><b>\ucd5c\uc6d0\ube48</b>: \ud504\ub860\ud2b8\uc5d4\ub4dc \uac1c\ubc1c\uc744 \uc9c4\ud589\ud560 \uc218\ub85d, <code>useEffect</code>\ub97c \\"\uc798 \uc4f0\ub824\uace0\\" \ub178\ub825\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \\"\uc548 \uc4f0\ub824\uace0\\" \ub178\ub825\ud558\uac8c \ub429\ub2c8\ub2e4. \uc544\ubb34\ub798\ub3c4 \uc120\uc5b8\uc801\uc778 \ud504\ub85c\uadf8\ub798\ubc0d\uc5d0\uc11c \ubc97\uc5b4\ub0a0 \uc218\ubc16\uc5d0 \uc5c6\uae30 \ub54c\ubb38\uc778 \uac83 \uac19\uc8e0. \ub354\uad70\ub2e4\uac00 18\ubc84\uc804\uc758 StrictMode\uc5d0\uc11c Effect\ub97c \ub450 \ubc88 \uc2e4\ud589\uc2dc\ud0a4\ub294 \uac83\uc740 \uc810\uc810 StrictMode\ub97c \ud3ec\uae30\ud558\uac8c \ub9cc\ub4ed\ub2c8\ub2e4. \uacf5\uc2dd\ubb38\uc11c\uc758 <a href=\\"https://ko.react.dev/learn/you-might-not-need-an-effect\\">you-might-not-need-an-effect</a> \uc640 \ub0b4\uc6a9\uc744 \uacf5\uc720\ud558\ubbc0\ub85c, \uba3c\uc800 \uc77d\uace0 \ub098\uc11c \uc601\uc0c1\uc744 \ub4e4\uc5b4\ubcf4\uc154\ub3c4 \uc88b\uc744 \uac83 \uac19\uc544\uc694.</p><p data-notion-block-id=\\"4855ab39-e8f7-4c7e-9363-0318e9b82061\\"><b>\uc2ec\uc724\uc12d</b>: hooks\uac00 \ucc98\uc74c \ub098\uc62c \ub54c(v16.8)\ub294 hooks\uc758 \uac1c\uc218\ub3c4 \uc81c\ud55c\uc801\uc774\uc600\uc744 \ubfd0\ub354\ub7ec \ud604\uc7ac\ucc98\ub7fc \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 \uc815\ub9bd\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uae30\uc874\uc758 <code>redux-thunk</code>\uc640 <code>redux-saga</code>\ub85c \uc11c\ubc84 \ub370\uc774\ud130\ub97c \uac00\uc838\uc624\uace4 \ud588\uc8e0. \ud558\uc9c0\ub9cc \uc9c0\uae08\uc740 \ub2e4\ub985\ub2c8\ub2e4. \uc11c\ubc84 \ub370\uc774\ud130\ub97c \uac00\uc838\uc624\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 \uc815\ub9bd\ub418\uc5c8\uace0, \ubaa8\ub4e0 \uc0c1\ud0dc\ub97c <code>useState</code>\uc5d0 \uc800\uc7a5\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub41c\ub2e4\ub77c\ub294 \uc815\ubcf4\ub294 \ub110\ub9ac \ud37c\uc84c\uc2b5\ub2c8\ub2e4. \uc774 \uc601\uc0c1\uc740 \uadf8\uc5d0 \ub9de\ucdb0\uc11c \uc0ac\uc774\ub4dc \uc774\ud399\ud2b8\uac00 \ud544\uc694\ud560 \ub54c\ub9cc <code>useEffect</code>\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc88b\ub2e4\ub294 \uc88b\uc740 \uc815\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d3817777-b71f-492c-8d36-a198fc03837b\\" id=\\"d3817777-b71f-492c-8d36-a198fc03837b\\"><b>\ud14c\uc2a4\ud2b8\ub97c \uc5b4\ub5bb\uac8c \uc368\uc57c \ud560\uae4c</b></h2><a href=\\"https://kentcdodds.com/blog/how-to-know-what-to-test\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kentcdodds.com/blog/how-to-know-what-to-test</a><p data-notion-block-id=\\"472f48a6-7eac-4b50-b909-68748f11f115\\"><b>\uc2ec\uc724\uc12d</b>: \uccab\ubc88\uc9f8 \uae00\uc740 \ud14c\uc2a4\ud2b8\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \uc18c\uac1c\uae00\uacfc FAQ\uc774\uba70, \ub450\ubc88\uc9f8 \uae00\uc740 \ud14c\uc2a4\ud2b8\ub97c \uc5b4\ub5bb\uac8c \uc811\uadfc\ud574\uc57c \ud558\ub294\uc9c0 \uc54c\ub824\uc90d\ub2c8\ub2e4. \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\uc11c \ud14c\uc2a4\ud2b8\ub97c \uc791\uc131\ud558\uac8c \ub418\uba74 \uae00\uc5d0\uc11c \ub9d0\ud558\ub294 use case testing\uc744 \ub9ce\uc774 \ud558\uac8c \ub429\ub2c8\ub2e4. \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc790\uc8fc \ubc14\uafd4\uc57c \ud560 \uc218\ub3c4 \uc788\uace0, \uc544\ub2c8\uba74 \uc544\uc608 \ud504\ub808\uc784\uc6cc\ud06c\ub97c \ubc14\uafd4\uc57c \ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc138\ubd80 \uad6c\ud604\uc5d0 \ub300\ud574 \ud14c\uc2a4\ud2b8\ub97c \ud558\uc9c0 \uc54a\uace0 \ub3d9\uc791\uc5d0 \ub300\ud574 \ud14c\uc2a4\ud2b8\ub97c \uc9c4\ud589\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774 \ub450 \uae00\uc744 \ud1b5\ud574 \ud14c\uc2a4\ud2b8\ub97c \uc2dc\uc791\ud574\ubcf4\uc138\uc694 \ud83d\ude03</p><p data-notion-block-id=\\"8b4e1fd8-dadf-422c-b077-af1674cdf8ba\\"><b>\ucd5c\uc6d0\ube48</b>: Use Case Coverage\ub97c 100%\ub85c \ub9de\ucd94\uae30 \uc704\ud55c \uc870\uac74\uc744 \uad6c\ud574\ub0b4\ub294 \uac83\uc740 \ud6c8\ub828\uc774 \ud544\uc694\ud55c \uac83 \uac19\uc544\uc694. \uc798 \ucd94\uc0c1\ud654\ub41c \uae30\ub2a5\uc744 \ub9cc\ub4e4\uac8c \ub41c\ub2e4\uba74, \ud55c\ubc88\uc529\uc740 \ub2e8\uc704 \ud14c\uc2a4\ud2b8\ub97c \ub9cc\ub4e4\uc5b4\ubcf4\ub294 \uacbd\ud5d8\uc744 \uac00\uc838\ubcf4\uba74 \uc88b\uaca0\uc8e0?</p><h2 data-notion-block-id=\\"8a4ee1bf-2fe6-4a80-ac51-4a47eeb3756b\\" id=\\"8a4ee1bf-2fe6-4a80-ac51-4a47eeb3756b\\">\uc88b\uc740 UI \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uae30\uc900</h2><a href=\\"https://www.builder.io/blog/25-plus-ui-component-libraries\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.builder.io/blog/25-plus-ui-component-libraries</a><p data-notion-block-id=\\"64494fe1-bd33-4fe0-8dc4-808c8222db29\\"><b>\uc2ec\uc724\uc12d</b>: UI\ud504\ub808\uc784\uc6cc\ud06c\uc758 \uc5ed\uc0ac\uc640 UI \ud504\ub808\uc784\uc6cc\ud06c \uc720\ud615\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uc88b\uc740 UI \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uae30\uc900\uc5d0 \ub300\ud574 \uc18c\uac1c\ud558\ub294\ub370, \uc774\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc758 \uc6d0\uce59\uc744 \ub9cc\ub4e4 \ub54c \uc5f0\uad00\uc9c0\uc744 \uc218 \uc788\uaca0\ub124\uc694 :)</p><p data-notion-block-id=\\"4ce6922b-3181-40a9-aafd-c2d08a8588e3\\"><b>\ucd5c\uc6d0\ube48</b>: UI \ub77c\uc774\ube0c\ub7ec\ub9ac \uc4f0\uc784\uc0c8\uc5d0 \ub9de\uac8c \ubd84\ub958\ud574\ub454 \uac83\uc774 \uc778\uc0c1\uc801\uc774\ub124\uc694. \ube44\uc2b7\ud574 \ubcf4\uc5ec\ub3c4 \ubd84\uba85\ud788 \ub2e4\ub978 \uc4f0\uc784\uc0c8\ub97c \uac00\uc9c0\uace0 \uc788\uc73c\ub2c8, \uc801\uc808\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc120\uc815\ud560 \ub54c \uc54c\uc544\ub450\uba74 \uc88b\uc740 \ub0b4\uc6a9\uc774\uc8e0. \uac70\uae30\uc5d0 \ud504\ub808\uc784\uc6cc\ud06c\ubcc4 \ubaa8\ub358\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc815\ub9ac\ub3fc\uc788\uc73c\ub2c8, \ud504\ub85c\uc81d\ud2b8\ub97c \uc2dc\uc791\ud560 \uc2dc\uc810\uc5d0 \uc77d\uc5b4\ubd10\ub3c4 \uc88b\uc744 \uac83 \uac19\uc544\uc694.</p><p data-notion-block-id=\\"49edcd89-0558-428b-a6a6-8a3558eec61f\\"><b>\uae40\ub300\uad00:</b> \ud3c9\uc18c UI \ud504\ub808\uc784\uc6cc\ud06c\ub97c \uc798 \ucc3e\uc9c0 \uc54a\uc558\uc5c8\ub294\ub370, \uad49\uc7a5\ud788 \ub9ce\uc740 \uc885\ub958\uac00 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5ee38179-00bb-4327-b3c8-fcd0727ac93f\\" id=\\"5ee38179-00bb-4327-b3c8-fcd0727ac93f\\">Portal \ud55c\ubc88 \uc368\ubcfc\ub798\uc694?</h2><a href=\\"https://semaphoreci.com/blog/react-portals\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://semaphoreci.com/blog/react-portals</a><p data-notion-block-id=\\"3842dc46-c561-4439-8e72-ebf42d7fd78b\\"><b>\uc2ec\uc724\uc12d:</b> Portal\uc740 \uc4f8 \uacbd\uc6b0\uac00 \ub4dc\ubb3c\uc9c0\ub9cc \uac15\ub825\ud55c \uae30\ub2a5\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. \uc774 \uae00\uc740 Portal\uc758 \uc0ac\uc6a9\ubc29\ubc95\uacfc \uc7a5\uc810, \uc8fc\uc758\uc0ac\ud56d\uc744 \uc54c\ub824\uc8fc\uba74\uc11c Portal\uc5d0 \uc785\ubb38\uc744 \ub3c4\uc640\uc90d\ub2c8\ub2e4. Portal\uae30\ub2a5\uc740 Vue, Solid\uc5d0\uc11c\ub3c4 \uc81c\uacf5\ud558\ub2c8 \uaf2d \uc0ac\uc6a9\uc0ac\ub840\ub97c \uae30\uc5b5\ud558\uace0 \uc801\uc6a9\ud558\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4!</p><p data-notion-block-id=\\"31722e8a-c929-4bb0-b19f-e69c61d9f4db\\"><b>\ucd5c\uc6d0\ube48</b>: Event Bubbling\uc774 DOM\uc758 \uad6c\uc870\ub300\ub85c \uc9c4\ud589\ub418\uc9c0 \uc54a\uace0, React\uc758 \ub80c\ub354 \ud2b8\ub9ac \uad6c\uc870\ub85c \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\uc744 \uc8fc\uc758\ud574\uc57c\uaca0\ub124\uc694! \uc313\uc784 \ub9e5\ub77d\uc744 \ud655\uc2e4\ud558\uac8c \ubc97\uc5b4\ub0a0 \uc218 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \ubc18\ub4dc\uc2dc \uc54c\uc544\uc57c \ud558\ub294 API\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"3bde45fc-a46a-4666-b120-d5529270bb88\\"><b>\uae40\ub300\uad00</b>: \ud56d\uc0c1 \ubaa8\ub2ec \uc0dd\uc131 \uc2dc\uc5d0 Portal\uc744 \ubb34\uc9c0\uc131\uc73c\ub85c \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc5c8\ub294\ub370, Event Bubbling \uc791\ub3d9 \ubb38\uc81c\uc640 \uc9c1\uc811\uc801\uc778 \uc131\ub2a5 \ubb38\uc81c\uc5d0 \uc5f0\uacb0\ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc744 \uc720\ub150\ud574\uc57c\uaca0\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e4\uac8c\ub418\ub294 \uae00\uc785\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"30fd9bf2-36bd-4f5d-afd4-7a8cad87d0ad\\" id=\\"30fd9bf2-36bd-4f5d-afd4-7a8cad87d0ad\\"><b>Static Hermes, RN\uc744 \ub354 \ube60\ub974\uac8c \ud574\uc90d\ub2c8\ub2e4.</b></h2><a href=\\"https://speakerdeck.com/tmikov2023/static-hermes-react-native-eu-2023-announcement\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://speakerdeck.com/tmikov2023/static-hermes-react-native-eu-2023-announcement</a><p data-notion-block-id=\\"5c5b76bc-2647-4f61-b5a1-14f9965cd343\\"><b>\uc2ec\uc724\uc12d</b>: Hermes\ub294 \uae30\uc874 JS \uc5d4\uc9c4\uc744 \ub300\uccb4\ud558\uc5ec React Native\uc758 \uc131\ub2a5\uc744 \ud5a5\uc0c1\ud588\uc2b5\ub2c8\ub2e4. \ucef4\ud30c\uc77c\uc744 \ube4c\ub4dc\ud0c0\uc784\uc5d0 \ud558\ub3c4\ub85d \ub9cc\ub4e4\uace0 \uc571 \uc2e4\ud589\uc2dc\uc5d0\ub294 \ubc14\uc774\ud2b8\ucf54\ub4dc\uac00 \uc2e4\ud589\ub418\uac8c \ub9cc\ub4e4\uc5b4 \uc2dc\uc791\uc2dc\uac04\uc744 \uc904\uc5ec \uc131\ub2a5\uc744 \ud5a5\uc0c1\ud55c \uac83\uc785\ub2c8\ub2e4(<a href=\\"https://medium.com/tilicholabs/what-makes-hermes-engine-react-native-fast-ac6fa5e3ad2e\\">\uc0c1\uc138\ud55c \uae00</a>). Static Hermes\ub294 TS, Flow\ub97c \ud65c\uc6a9\ud558\uc5ec JS\ub97c \uc870\uac74\ubd80 \ucef4\ud30c\uc77c\uc744 \ud574\uc11c native code\ub97c \ub354 \uc548\uc804\ud558\uac8c \ubd88\ub7ec\uc640\uc11c \ub354 \uc131\ub2a5\uc744 \ub04c\uc5b4\uc62c\ub9b0\ub2e4\uace0 \ud569\ub2c8\ub2e4. \uc88b\ub124\uc694!</p><h2 data-notion-block-id=\\"ac31d974-03d9-4d46-94aa-cce3a21217a6\\" id=\\"ac31d974-03d9-4d46-94aa-cce3a21217a6\\"><b>Next.js\uc758 App router\ub294 \uc2dc\uae30\uc0c1\uc870\ub2e4.</b></h2><a href=\\"https://pilcrow.vercel.app/blog/nextjs-why\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://pilcrow.vercel.app/blog/nextjs-why</a><p data-notion-block-id=\\"bbe63194-9842-4174-9acb-dde18c1c6fc0\\"><b>\uc2ec\uc724\uc12d</b>: Next.js 13\ubc84\uc804\uc5d0 \ubaa8\ub4e0 \uac83\uc744 \ubc14\uafb8\ub294 App router\ub97c \ucd9c\uc2dc\ud558\uba74\uc11c production-ready\ub77c\uace0 \ud558\uc9c0\ub9cc\u2026 \uae30\uc874\uc758 \uac83\uc744 \uc644\ubcbd\ud558\uac8c \ub300\uccb4\ud558\uc9c0 \uc54a\uc744 \ubfd0\ub354\ub7ec \ubd88\uc548\uc815\ud558\ub2e4\ub294 \uac83\uc744 \uc54c\uac8c \ub429\ub2c8\ub2e4. \uc774 \uae00\uc740 Next.js app router\uac00 \uc544\uc9c1\uc740 \ubd88\uc548\uc815\ud558\ub2e4\ub77c\ub294 \uac83\uc744 \uc54c\ub824\uc8fc\uba74\uc11c \ubd88\ub9cc\uc2a4\ub7ec\uc6b4 \uc810\uc744 \ud1a0\ub85c\ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"2bfd89de-a019-497f-841e-2bed15dd8ba4\\"><b>\uae40\ub300\uad00</b>: Next.js\ub97c \uc0ac\uc6a9\ud558\uba74\uc11c \ub2e4\uc591\ud55c \ubb38\uc81c\uc640 \uc77c\uad00\uc131 \uc5c6\ub294 API \uc5d0 \ub300\ud55c \ubd88\ub9cc\uc5d0 \ub300\ud55c \uc774\uc57c\uae30\uc640, \ucfe0\ud0a4\uc640 API \ud5e4\ub354\ub97c \uac1c\ubc1c\uc790\uac00 \uadf9\ud788 \uc81c\ud55c\uc801\uc73c\ub85c \ucee8\ud2b8\ub864\ud560 \uc218 \uc788\ub294 \ubd80\ubd84\uc5d0 \ub300\ud574 \uc9c0\uc801\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud574\ub2f9 \uae00\uc744 \ud1b5\ud574 Edge\uc5d0\uc11c \ubbf8\ub4e4\uc6e8\uc5b4\uac00 \uc81c\ud55c\uc801\uc73c\ub85c \uc791\ub3d9\ud558\ub294 \ubb38\uc81c\uc640 Next.js\uc5d0 \ub300\ud55c \ubb38\uc81c\ub97c \uac04\uc811\uc801\uc73c\ub85c \uacbd\ud5d8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ce10cc26-ec71-4794-a0c9-bcf135e146f6\\" id=\\"ce10cc26-ec71-4794-a0c9-bcf135e146f6\\">CSS\ub97c \ub3d9\uc801\uc73c\ub85c \ub9cc\ub4e4\uae30</h2><a href=\\"https://moderncss.dev/how-custom-property-values-are-computed/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://moderncss.dev/how-custom-property-values-are-computed/</a><p data-notion-block-id=\\"20ddce54-c9c3-4898-b71f-3e340d15a19c\\"><b>\uae40\ub300\uad00</b>: CSS \ucee4\uc2a4\ud140 \ud504\ub85c\ud37c\ud2f0 \uacc4\uc0b0\uc774 \uc5b4\ub5bb\uac8c \uc774\ub8e8\uc5b4\ub294\uc9c0\uc5d0 \ub300\ud55c \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub358 CSS \uc9c0\uc6d0\uc5d0\uc11c \uacc4\uc0b0\ub41c \uac12\uc758 \uc601\ud5a5\uc744 \uc774\ud574\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\uba70, \ucee4\uc2a4\ud140 \ud504\ub85c\ud37c\ud2f0\uc758 \uac12\uc744 \uacc4\uc0b0\ud558\ub294 \ubc29\uc2dd\uc774 \uc0c1\uc18d\uc5d0 \uc5b4\ub5bb\uac8c \uc601\ud5a5\uc744 \uc8fc\ub294\uc9c0\ub3c4 \uc54c\ub824\uc8fc\ub2c8 CSS \uc791\uc131\ud560 \ub54c \ub9ce\uc740 \ub3c4\uc6c0\uc774 \ub418\ub294 \ub0b4\uc6a9\uc785\ub2c8\ub2e4!</p><p data-notion-block-id=\\"86ce968f-d8af-4f87-9302-18c1a40f263e\\"><b>\uc2ec\uc724\uc12d</b>: CSS\ub97c \ub3d9\uc801\uc73c\ub85c \ucf54\ub529\ud560 \uc218 \uc788\ub3c4\ub85d \ub9cc\ub4e0 CSS \ubcc0\uc218(custom property\ub77c\uace0\ub3c4 \ubd88\ub9bc)\uc740 \ub9e4\uc6b0 \uc720\uc6a9\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc fallback\uc744 \ub123\ub294 \ubc29\ubc95, \uacc4\uc0b0\ub418\ub294 \ubc29\ubc95\uc744 \ubaa8\ub974\ub294 \uc0ac\ub78c\ub3c4 \ub9ce\uc2b5\ub2c8\ub2e4(CSS \ubcc0\uc218\ub97c \ubaa8\ub974\ub294 \uc0ac\ub78c\ub3c4 \uc788\uad6c\uc694). CSS \ubcc0\uc218\ub97c \uc0ac\uc6a9\ud55c\ub2e4\uba74 \ud765\ubbf8\ub86d\uac8c \ubcfc \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4. \ucd94\uac00\ub85c <code>@supports</code>\ub97c \ud1b5\ud55c fallback \ubc29\ubc95\uae4c\uc9c0 \uc54c\ub824\uc90d\ub2c8\ub2e4!</p><p data-notion-block-id=\\"edf21c34-abe7-4f52-a66c-db48a02db7f2\\"><b>\ucd5c\uc6d0\ube48</b>: <code>@supports</code>\ub85c css\uc5d0 fallback\uc744 \ub2f4\ub294\ub2e4\ub294\uac8c \uc2e0\uae30\ud558\ub124\uc694. custom property\ub97c \uc790\uc8fc \uc0ac\uc6a9\ud558\uc9c4 \uc54a\uc558\uc9c0\ub9cc, \ud639 \ub514\uc790\uc778 \uad00\ub828 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \uae30\uc5ec\ud558\uac8c \ub41c\ub2e4\uba74 \uc720\uc6a9\ud558\uac8c \uc4f8 \uc218 \uc788\uc744 \uac83 \uac19\uc544\uc694.</p><h2 data-notion-block-id=\\"58a97175-697e-41d5-8edc-852bed4754a7\\" id=\\"58a97175-697e-41d5-8edc-852bed4754a7\\">JS Closures \uac00\uc774\ub4dc</h2><a href=\\"https://ui.dev/ultimate-guide-to-execution-contexts-hoisting-scopes-and-closures-in-javascript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ui.dev/ultimate-guide-to-execution-contexts-hoisting-scopes-and-closures-in-javascript</a><p data-notion-block-id=\\"1953dc41-e28f-4230-8659-fe97f51acb38\\"><b>\uc2ec\uc724\uc12d</b>: \uc2e4\ud589 \ucee8\ud14d\uc2a4\ud2b8\ub294 \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ubcf8\uccb4\ub77c\uace0 \ubcfc \uc218 \uc788\uc744 \uc815\ub3c4\ub85c \uae30\ubcf8\uc801\uc778 \uac1c\ub150\uc774\uc790 \ud55c \ubc88\uc5d0 \uc774\ud574\ud558\uae30 \uc5b4\ub824\uc6b4 \uac1c\ub150\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uaf2d \uc54c\uc544\uc57c \ud558\ub2c8 \uc88b\uc740 \uc2dc\uac01\ud654 \uc790\ub8cc\uc640 \ud568\uaed8 \uc124\uba85\ub41c \uae00\uc744 \ubcf4\uc138\uc694 \ud83d\ude0a \ub354 \uae4a\uc740 \uac1c\ub150\uc744 \uc6d0\ud55c\ub2e4\uba74 <a href=\\"https://ko.javascript.info/closure\\">\uc774 \uc790\ub8cc</a>\ub3c4 \ubd10\uc8fc\uc138\uc694!</p><p data-notion-block-id=\\"9b491d4d-bbd0-4218-9161-9c7ac07b8a80\\"><b>\ucd5c\uc6d0\ube48</b>: \uc2a4\ucf54\ud504 \uccb4\uc774\ub2dd\uc740 \ud655\uc2e4\ud558\uac8c \uc774\ud574\ud558\uc9c0 \uc54a\uc73c\uba74 \ub9e4\ubc88 \ud5f7\uac08\ub9ac\ub294 \uac83 \uac19\uc544\uc694. \uc88b\uc740 \uc608\uc81c \ucf54\ub4dc\uc640 \ub3c4\uc2dd\ud654\ub85c \uac10\uc744 \uc7a1\uae30 \uc88b\uc740 \uae00\uc774\ub124\uc694. \uc800\ub294 <a href=\\"https://youtu.be/EWfujNzSUmw?si=duCLVxbf3xqVSiid\\">\uc6b0\uc544\ud55c\ud14c\ud06c\ucf54\uc2a4\uc758 \ud14c\ucf54\ud1a1</a> \uc601\uc0c1\uc744 \ubcf4\uace0 \ub09c \ub4a4\ub860 \uba85\ud655\ud558\uac8c \uc774\ud574\ud588\ub294\ub370\uc694, \ucc98\uc74c \uac1c\ub150\uc744 \ub4e3\ub294 \ubd84\ub4e4\uaed8\ub3c4 \uc27d\uace0 \ubcf4\uae30\uc88b\uac8c \uc124\uba85\ud55c \uc601\uc0c1\uc774\ub77c \ucd94\ucc9c\ub4dc\ub824\uc694.</p><h1 data-notion-block-id=\\"7a575204-726a-4c74-a77f-18b87c3c4349\\">Infcon 2023</h1><h2 data-notion-block-id=\\"6141e471-b6ad-480c-ac5d-375924768e2d\\" id=\\"6141e471-b6ad-480c-ac5d-375924768e2d\\">\uc778\ud130\ub809\ud2f0\ube0c \uac1c\ubc1c</h2><a href=\\"https://inflearn.com/conf/infcon-2023/session-detail?id=768\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://inflearn.com/conf/infcon-2023/session-detail?id=768</a><p data-notion-block-id=\\"29420c7e-17ce-45a5-84f6-8246bb1e70ec\\"><b>\uc2ec\uc724\uc12d</b>: WebGL\uacfc Three.js\uc758 \uac00\ubcbc\uc6b4 \uc18c\uac1c\uac19\uc740 \ubc1c\ud45c\uc785\ub2c8\ub2e4. WebGL\uc740 \uc544\ubb34\ub798\ub3c4 \ub9ce\uc740 \uac1c\ubc1c\uc790\uc5d0\uac8c \uc5b4\uc0c9\ud560 \uc218 \uc788\ub294\ub370 \uc798 \uc124\uba85\ud574 \uc8fc\uc168\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. Three.js \uac15\uc758\ub85c \uc774 <a href=\\"https://threejs-journey.com/\\">\uac15\uc758</a>\ub97c \uc18c\uac1c\ud574\uc8fc\uc168\ub294\ub370, \uc785\ubb38\ud558\uae30\uc5d4 \uc774 <a href=\\"https://discoverthreejs.com/\\">\uc6f9\ud398\uc774\uc9c0</a>\ub3c4 \ub098\uc058\uc9c0 \uc54a\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4 \ud83d\ude42</p><p data-notion-block-id=\\"06ee6eb9-bff6-4fc6-859c-eec0cd61bf1b\\"><b>\ucd5c\uc6d0\ube48</b>: \ud574\ub2f9 \ubd80\ubd84\uc744 \uac1c\ubc1c\ud560 \uc77c\uc740 \uc801\uaca0\uc9c0\ub9cc, \uc0dd\uc18c\ud55c \ubd80\ubd84\uc774\ub2e4\ubcf4\ub2c8 \uc624\ud788\ub824 \ub4e3\ub294\ub370 \uc7ac\ubbf8\uc788\ub124\uc694. WebGL\uc774\ub77c\ub294 \ud0a4\uc6cc\ub4dc\ub9cc \uc54c\uc544\ub46c\ub3c4 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud574\uc694.</p><h2 data-notion-block-id=\\"21ced923-fba6-4bff-8458-46b84b849fdd\\" id=\\"21ced923-fba6-4bff-8458-46b84b849fdd\\">Automated Testing on \uc6f9\uc0ac\uc774\ud2b8</h2><a href=\\"https://www.inflearn.com/conf/infcon-2023/session-detail?id=752\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.inflearn.com/conf/infcon-2023/session-detail?id=752</a><p data-notion-block-id=\\"776ebc9f-b30f-4d0e-9dd6-9124d17b2688\\"><b>\uc2ec\uc724\uc12d</b>: Lighthouse\uacfc Web Vitals\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \uc18c\uac1c\uc785\ub2c8\ub2e4. Lighthouse\ub294 \uc2e4\uc81c \ub514\ubc14\uc774\uc2a4\uc640 \ube44\uc2b7\ud558\uac8c \ud14c\uc2a4\ud2b8\ub97c \uc9c4\ud589\ud558\uc5ec Web Vitals\uc5d0 \ubb38\uc81c\uac00 \ub418\ub294 \ubd80\ubd84\uc744 \ud0d0\uc9c0\ud558\uc5ec \uace0\uce58\ub3c4\ub85d \uc720\ub3c4\ud569\ub2c8\ub2e4. \uc2e4\uc81c \ud074\ub77c\uc774\uc5b8\ud2b8\uc758 \ub370\uc774\ud130\ub97c \ubcf4\uace0 \uc2f6\ub2e4\uba74 CruX\uc5d0 \ub300\ud55c \uc815\ubcf4\ub97c \ub2e4\ub8ec <a href=\\"https://blog.doctor-cha.com/why-google-does-not-use-lighthouse\\">\uc774 \uae00</a>\uc744 \ubcf4\uace0 \uc5ec\ub7ec \ub370\uc774\ud130\ub97c \ud1b5\ud574 \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \uc88b\uc740 UX\ub97c \uac00\uc9c0\ub294\uc9c0 \ud655\uc778\ud574\ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4.</p><p data-notion-block-id=\\"f7227147-6d97-4f59-93eb-635930a3c731\\"><b>\ucd5c\uc6d0\ube48</b>: chrome lighthouse\ub97c \ud65c\uc6a9\ud558\uae30\uc5d0 \uc55e\uc11c \uae30\ucd08\uc801\uc778 \uc124\uba85\ubd80\ud130 \ucc9c\ucc9c\ud788 \ud574\uc8fc\ub124\uc694. \ud639 \uc544\uc9c1 \ubcf8\uc778 \ud504\ub85c\uc81d\ud2b8\uc758 \uc131\ub2a5\uce21\uc815\uc744 \uc548\ud574\ubcf4\uc168\ub2e4\uba74, \uc774 \uac15\uc758\ub97c \ub4e3\uace0 \ubc14\ub85c \ud655\uc778\ud574\ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub824\uc694!</p><h2 data-notion-block-id=\\"bd72fb7b-20cd-420d-a203-9baffa0f64c6\\" id=\\"bd72fb7b-20cd-420d-a203-9baffa0f64c6\\">\uc9d1\ud569\uc73c\ub85c \uc774\ud574\ud558\ub294 \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8</h2><a href=\\"https://www.inflearn.com/conf/infcon-2023/session-detail?id=770\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.inflearn.com/conf/infcon-2023/session-detail?id=770</a><p data-notion-block-id=\\"c5c393b6-3e4d-4e78-a025-73a362e22ff7\\"><b>\uc2ec\uc724\uc12d</b>: \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ud0c0\uc785 \uc785\ubb38\ud558\ub294 \uc0ac\ub78c\uc774 \ubcf4\uae30 \uc88b\uc740 \ubc1c\ud45c\uc785\ub2c8\ub2e4! \uc5c5/\ub2e4\uc6b4 \uce90\uc2a4\ud305\uc5d0 \ub300\ud574 \uc774\uc57c\uae30 \ud558\uba74\uc11c \uae30\ubcf8 \ud0c0\uc785, \uc720\ub2c8\uc628 \ud0c0\uc785\uc774\ub098 \uad50\ucc28 \ud0c0\uc785\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ub354\uc6b1 \uae4a\uac8c \ub4e4\uc5b4\uac00\uba74 \uc5c5\uce90\uc2a4\ud305\uacfc \uad00\ub828\ub41c <a href=\\"https://seob.dev/posts/%EA%B3%B5%EB%B3%80%EC%84%B1%EC%9D%B4%EB%9E%80-%EB%AC%B4%EC%97%87%EC%9D%B8%EA%B0%80/\\">\uacf5\ubcc0\uc131</a>\uc5d0 \ub300\ud574 \uc54c\uc544\ubcf4\ub294 \uac83\uc774 \uc88b\uc2b5\ub2c8\ub2e4 \ud83d\ude00 \ub2e4\ub978 \uc5b8\uc5b4\uc5d0\uc11c\ub294 \uc5b4\ub5bb\uac8c \uc801\uc6a9\ub418\ub294\uc9c0 \ud655\uc778\ud558\ub824\uba74 <a href=\\"https://tech.devsisters.com/posts/programming-languages-2-polymorphism\\">\uc774 \uae00</a>\ub3c4 \ud655\uc778\ud574\ubcf4\uc138\uc694. \uc74c! \uc5b4\ub835\ub2e4!</p><p data-notion-block-id=\\"4e548e1c-b08c-4dc5-838c-31735d11bf23\\"><b>\ucd5c\uc6d0\ube48</b>: <code>never</code> , <code>unknown</code> , <code>any</code> \ub77c\ub294 \ud2b9\uc218 \ud0c0\uc785\ub4e4\uc5d0 \ub300\ud574 \uc27d\uac8c \uc774\ud574\ud560 \uc218 \uc788\ub294 \uac15\uc758\ub124\uc694. <code>as</code> \ub97c \ud65c\uc6a9\ud55c \ud0c0\uc785 \ub2e8\uc5b8\uc744 \uc9c4\ud589\ud560 \ub54c\uc640, \uc720\ub2c8\uc628 \ud0c0\uc785\uc744 \ud65c\uc6a9\ud558\uac8c \ub420 \uacbd\uc6b0 \uc5c5-\ub2e4\uc6b4 \uce90\uc2a4\ud305\uc5d0 \ub300\ud55c \uc774\ud574\uac00 \uc788\ub2e4\uba74 \ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ube68\uac04\uc904\uc774 \uc804\ud600 \ub450\ub835\uc9c0 \uc54a\uc744 \uac83 \uac19\uc544\uc694!</p><h2 data-notion-block-id=\\"1aea1962-b013-470c-867d-adcc2ab5b41b\\" id=\\"1aea1962-b013-470c-867d-adcc2ab5b41b\\">\ubaa8\ub178\ub808\ud3ec \uc801\uc6a9\uae30</h2><a href=\\"https://inflearn.com/conf/infcon-2023/session-detail?id=746\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://inflearn.com/conf/infcon-2023/session-detail?id=746</a><p data-notion-block-id=\\"758f9cc0-d3b5-4ffc-8f8c-1cd142b76842\\"><b>\uc2ec\uc724\uc12d</b>: \uac04\ub2e8\ud55c Turborepo \uc801\uc6a9\uae30\ub97c \uc124\uba85\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/37768805-783a-4a80-9c35-444e5dabff7a#d97e235c-7dad-4ca7-ab73-91acb8f10219\\">\uc774\uc804\uc758 \uac16\uace0\uc654\ub358 \uae00</a>\uc744 \uc0c1\uc138\ud558\uac8c \ud480\uc5b4\ub0b8 \ubc1c\ud45c\ub77c\uace0 \ubcfc \uc218 \uc788\uaca0\ub124\uc694. \ubaa8\ub178\ub808\ud3ec\ub97c \ub3c4\uc785\ud55c \uc774\uc720\ub97c \uc0c1\uc138\ud558\uac8c \uc124\uba85\ud558\uace0 \uc788\uc73c\ub2c8 \ud55c \ubc88 \ubcf4\uc2dc\uba74 \ubaa8\ub178\ub808\ud3ec\ub97c \ub3c4\uc785\ud558\ub294 \uc774\uc720\ub97c \uc774\ud574\ud558\ub294\ub370 \ub3c4\uc6c0\uc774 \ub420 \uac70\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p>"}')}}]);